<?php
namespace App\Http\Controllers;
use App\Models\User; use App\Services\AuditoriaService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Validation\ValidationException; use Inertia\Inertia;
class AuthController extends Controller { public function loginForm(){return Inertia::render('Auth/Login');} public function login(Request $r,AuditoriaService $audit){$v=$r->validate(['email'=>'required|email','password'=>'required|string']);if(!Auth::attempt($v,$r->boolean('remember')))throw ValidationException::withMessages(['email'=>'Credenciales incorrectas.']);$r->session()->regenerate();$audit->registrar($r,'auth.login');return redirect()->intended('/catalogo');} public function registerForm(){return Inertia::render('Auth/Register');} public function register(Request $r,AuditoriaService $audit){$v=$r->validate(['name'=>'required|string|max:255','email'=>'required|email|max:255|unique:users','password'=>'required|string|min:8|confirmed','telefono'=>'nullable|string|max:32']);$u=User::create($v+['role'=>'Cliente']);Auth::login($u);$r->session()->regenerate();$audit->registrar($r,'auth.register');return redirect('/catalogo');} public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/catalogo');} }
